<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { IconCheck, IconCloud, IconCopy, IconFile, IconFolder, IconLink, IconLoader2, IconRefresh, IconSearch, IconSettings } from '@tabler/icons-vue'
import ManagementLayout from '../components/ManagementLayout.vue'
import STRMDirectoryDialog from '../components/STRMDirectoryDialog.vue'
import { useED2KSTRM } from '../composables/useED2KSTRM'
import { ed2kCacheStatus, ed2kDate, ed2kResourceActive, ed2kResourceAttention, ed2kResourceKey, ed2kResourceStatus, ed2kSize, ED2K_IMPORT_LIMIT } from '../utils/ed2kSTRM'
import { strmDirectoryPath } from '../utils/strmDirectory'
import { copyText } from '../utils/clipboard'

const props = defineProps<{ token: string }>()
defineEmits<{ logout: [] }>()
const { state, draft, loading, refreshing, busy, error, notice, input, query, links, resources, activeCount, readyCount, settingsDirty, needsSettingsSave, settingsValid, canStart, canImport, refresh, saveSettings, resetSettings, importLinks, resourceAction } = useED2KSTRM(() => props.token)
const directoryOpen = ref(false), copied = ref('')
async function copyPath(value: string) {
  try { await copyText(value); copied.value = value }
  catch { error.value = '复制失败，请重试' }
}
onMounted(() => { document.title = 'ED2K STRM · Cinema115' })
</script>

<template>
  <ManagementLayout title="ED2K STRM" description="接收 ED2K，生成可复用的 STRM，并在需要时恢复云端缓存。" :parent="{ label: '115 网盘', to: '/115' }" @logout="$emit('logout')">
    <template #actions><button type="button" class="es-button" :disabled="refreshing || !!busy" @click="refresh"><IconRefresh :size="17" aria-hidden="true" :class="{ 'es-spin': refreshing }" />{{ refreshing ? '刷新中…' : '刷新状态' }}</button></template>
    <p v-if="error" role="alert" class="es-alert">{{ error }} <button v-if="!state" type="button" :disabled="refreshing" class="es-text-button" @click="refresh">重新加载</button></p>
    <p v-if="notice" role="status" class="es-notice">{{ notice }}</p>
    <p v-if="state && !state.accountReady" role="status" class="es-alert">请先在 <RouterLink to="/helper115">115 助手</RouterLink> 配置并登录主账号。基础设置可先保存。</p>
    <p v-if="loading" role="status" class="es-empty">正在读取 ED2K STRM 配置…</p>
    <template v-else-if="state && draft">
      <div class="es-top-grid">
        <form class="es-panel" aria-label="ED2K STRM 基础设置" @submit.prevent="saveSettings">
          <header class="es-panel-heading"><h2><IconSettings :size="19" aria-hidden="true" />基础设置</h2><span v-if="settingsDirty" class="es-draft">未保存</span></header>
          <p class="es-help">此模块独立管理缓存和输出，已接受的任务继续使用提交时的设置。</p>
          <fieldset :disabled="!!busy" class="es-fields">
            <label class="es-field"><span>STRM 播放地址</span><input v-model="draft.baseUrl" type="url" required placeholder="http://NAS_IP:8080" aria-describedby="es-base-help" /><small id="es-base-help">填写播放器或 Emby 能访问的 Cinema115 地址。</small></label>
            <div class="es-field"><label for="es-output">本地输出目录</label><div class="es-directory-input"><input id="es-output" v-model="draft.outputDir" required placeholder="ed2k" aria-describedby="es-output-help" /><button type="button" class="es-button" @click="directoryOpen = true"><IconFolder :size="17" aria-hidden="true" />选择目录</button></div><small id="es-output-help">STRM 根目录内的相对路径，当前输出到 {{ strmDirectoryPath(draft.outputDir) }}。</small></div>
          </fieldset>
          <div class="es-cache"><IconCloud :size="18" aria-hidden="true" /><div><span>主网盘缓存目录</span><p>{{ state.cachePath || (state.cacheCID ? `缓存目录 ${state.cacheCID}` : '首次任务由系统创建专用目录') }}</p><small v-if="state.cacheCID">CID {{ state.cacheCID }}</small></div></div>
          <footer class="es-form-actions"><button v-if="settingsDirty" type="button" class="es-text-button" :disabled="!!busy" @click="resetSettings">还原修改</button><button type="submit" class="es-button es-primary" :disabled="!!busy || !settingsValid || !needsSettingsSave"><IconCheck v-if="!needsSettingsSave" :size="16" aria-hidden="true" />{{ busy === 'settings' ? '保存中…' : needsSettingsSave ? '保存设置' : '已保存' }}</button></footer>
        </form>
        <form class="es-panel es-import" aria-label="导入 ED2K" @submit.prevent="importLinks">
          <header class="es-panel-heading"><h2><IconLink :size="19" aria-hidden="true" />导入 ED2K</h2><span class="es-counter">每次最多 {{ ED2K_IMPORT_LIMIT }} 条</span></header>
          <p class="es-help">粘贴链接或包含 ED2K 的消息。同一资源会复用已有记录，文件名变化不会重复离线。</p>
          <label class="es-field es-link-input"><span>ED2K 链接</span><textarea v-model="input" rows="6" maxlength="409600" placeholder="ed2k://|file|影片.mkv|文件字节数|ED2K哈希|/" :disabled="!!busy" aria-describedby="es-import-help" /></label>
          <p id="es-import-help" class="es-help">{{ !state.accountReady ? '请先登录主账号。' : !state.settingsSaved ? '请先保存基础设置。' : settingsDirty ? '请先保存或还原基础设置，再导入链接。' : '提交后在后台等待文件可用，核验资料后生成 STRM。' }}</p>
          <footer class="es-form-actions"><span :class="links.length > ED2K_IMPORT_LIMIT ? 'es-error-text' : 'es-counter'">已识别 {{ links.length }} 条链接</span><button type="submit" class="es-button es-primary" :disabled="!canImport"><IconLoader2 v-if="busy === 'imports'" class="es-spin" :size="17" aria-hidden="true" /><IconFile v-else :size="17" aria-hidden="true" />{{ busy === 'imports' ? '提交中…' : '导入并生成 STRM' }}</button></footer>
        </form>
      </div>
      <section class="es-resources" aria-label="ED2K 资源">
        <header class="es-resources-heading"><div><h2>资源记录<span class="es-counter">{{ state.resources.length }}</span></h2><p class="es-help">已生成 {{ readyCount }} 项<span v-if="activeCount">，后台处理中 {{ activeCount }} 项</span>。列表刷新不会触发离线恢复。</p></div><label class="es-search"><IconSearch :size="17" aria-hidden="true" /><input v-model="query" type="search" aria-label="筛选 ED2K 资源" placeholder="搜索名称、哈希或路径" /></label></header>
        <div v-if="!resources.length" class="es-empty"><IconFile :size="28" aria-hidden="true" /><p>{{ query.trim() ? '没有匹配的资源' : '尚无资源，导入 ED2K 后将在这里显示生成进度。' }}</p><button v-if="query.trim()" type="button" class="es-text-button" @click="query = ''">清除筛选</button></div>
        <div v-else class="es-resource-grid">
          <article v-for="resource in resources" :key="ed2kResourceKey(resource)" class="es-resource" :aria-label="resource.name">
            <header class="es-resource-heading"><span class="es-file-symbol"><IconFile :size="21" aria-hidden="true" /></span><div><h3>{{ resource.name }}</h3><p class="es-resource-meta">{{ ed2kSize(resource.size) }}</p></div></header>
            <div class="es-resource-tags"><span class="es-status" :class="{ 'es-working': ed2kResourceActive(resource), 'es-attention': ed2kResourceAttention(resource) }"><IconLoader2 v-if="ed2kResourceActive(resource)" class="es-spin" :size="13" aria-hidden="true" />{{ ed2kResourceStatus(resource) }}</span><span class="es-cache-status">{{ ed2kCacheStatus(resource) }}</span></div>
            <p v-if="resource.message" class="es-resource-message" :class="{ 'es-error-text': ed2kResourceAttention(resource) }">{{ resource.message }}</p>
            <div v-if="resource.strmPath" class="es-output"><IconFolder :size="15" aria-hidden="true" /><span>{{ resource.strmPath }}</span><button type="button" class="es-icon-button" :aria-label="'复制' + resource.name + '的 STRM 路径'" :title="copied === resource.strmPath ? '已复制' : '复制路径'" @click="copyPath(resource.strmPath)"><IconCheck v-if="copied === resource.strmPath" :size="15" aria-hidden="true" /><IconCopy v-else :size="15" aria-hidden="true" /></button></div>
            <details class="es-identities"><summary>文件资料</summary><dl><div><dt>ED2K</dt><dd>{{ resource.hash }}</dd></div><div><dt>SHA1</dt><dd>{{ resource.sha1 || '文件可用后读取' }}</dd></div><div><dt>字节大小</dt><dd>{{ resource.size.toLocaleString('zh-CN') }}</dd></div></dl></details>
            <p class="es-updated">更新于 {{ ed2kDate(resource.updatedAt) }}</p>
            <footer class="es-resource-actions"><button type="button" class="es-button" :disabled="!!busy || !canStart || ed2kResourceActive(resource)" @click="resourceAction(resource, 'check')"><IconSearch :size="16" aria-hidden="true" />{{ busy === 'check:' + ed2kResourceKey(resource) ? '核验中…' : '核验缓存' }}</button><button type="button" class="es-button es-secondary" :disabled="!!busy || !canStart || ed2kResourceActive(resource)" @click="resourceAction(resource, 'restore')"><IconRefresh :size="16" aria-hidden="true" />{{ busy === 'restore:' + ed2kResourceKey(resource) ? '提交中…' : '恢复缓存' }}</button></footer>
          </article>
        </div>
      </section>
    </template>
    <STRMDirectoryDialog v-if="directoryOpen && draft" :token="token" title="选择 ED2K STRM 输出目录" @close="directoryOpen = false" @select="draft.outputDir = $event; directoryOpen = false" />
  </ManagementLayout>
</template>

<style scoped>
