.es-top-grid { display: grid; gap: 20px; align-items: stretch; }.es-panel { padding: 22px; display: flex; flex-direction: column; }.es-panel-heading, .es-resources-heading, .es-resource-heading { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; }.es-panel-heading h2, .es-resources-heading h2 { display: flex; align-items: center; gap: 9px; font-size: 15px; font-weight: 600; }.es-panel-heading h2 svg { color: #2563eb; }.es-help { margin-top: 8px; font-size: 12px; line-height: 1.8; color: rgb(var(--color-slate-500)); }.es-counter, .es-draft { color: rgb(var(--color-slate-500)); font-size: 12px; font-weight: 400; line-height: 1.8; }.es-draft { color: #b45309; }.es-fields { display: grid; gap: 18px; margin-top: 20px; min-width: 0; }.es-field { display: grid; gap: 8px; min-width: 0; font-size: 13px; color: rgb(var(--color-slate-700)); }.es-field > span, .es-field > label { font-weight: 500; }.es-field input, .es-field textarea { width: 100%; min-width: 0; padding: 10px 12px; border: 1px solid rgb(var(--color-slate-200)); border-radius: 9px; background: rgb(var(--surface-card)); color: rgb(var(--color-slate-900)); font-size: 13px; outline: none; }.es-field textarea { resize: vertical; min-height: 152px; line-height: 1.8; }.es-field small { color: rgb(var(--color-slate-500)); font-size: 11px; line-height: 1.7; overflow-wrap: anywhere; }.es-field input:focus, .es-field textarea:focus { border-color: #3b82f6; box-shadow: 0 0 0 3px rgb(59 130 246 / .1); }.es-directory-input { display: flex; gap: 8px; min-width: 0; }.es-directory-input > input { flex: 1; }.es-directory-input > button { flex-shrink: 0; }.es-cache { display: flex; align-items: flex-start; gap: 10px; margin: 20px 0; padding: 12px; border-radius: 10px; background: rgb(var(--color-slate-50)); color: rgb(var(--color-slate-500)); }.es-cache svg { margin-top: 1px; flex-shrink: 0; }.es-cache > div { min-width: 0; }.es-cache span { font-size: 12px; font-weight: 500; color: rgb(var(--colo