1px; }.es-identities summary { cursor: pointer; padding: 6px 0; width: fit-content; }.es-identities dl { display: grid; gap: 7px; padding-top: 7px; }.es-identities dl > div { display: grid; gap: 3px; }.es-identities dd { font-family: ui-monospace, monospace; overflow-wrap: anywhere; }.es-updated { margin-top: auto; padding-top: 14px; font-size: 10px; line-height: 1.8; color: rgb(var(--color-slate-500)); }.es-resource-actions { display: flex; gap: 8px; margin-top: 14px; padding-top: 14px; border-top: 1px solid rgb(var(--color-slate-100)); }.es-resource-actions > button { flex: 1; }.es-button:focus-visible, .es-text-button:focus-visible, .es-icon-button:focus-visible, .es-identities summary:focus-visible, .es-search:focus-within { outline: 2px solid #3b82f6; outline-offset: 3px; }
